using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.AlgebraicBoundary;
internal sealed class OriginalBoundaryHostDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The original entire-boundary and arbitrary-unit host.",
        H("The original entire-boundary and arbitrary-unit host"),
        Blocks(Describe.Lean(
            DescribeId.Create("original-entire-boundary-host"),
            DeclarationHandle.Create("D5/S3/Geometry/AlgebraicBoundary/OriginalBoundaryHost.original_entire_boundary_host"),
            H("Original entire-boundary host"),
            StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every nonzero finite-dimensional real carrier E, every closed convex cone C with nonempty ambient interior and salient underlying cone, and every original continuous linear unit u strictly positive on C except at zero, the declaration concludes the full section, quantum minimum, radial, arbitrary-degree ideal, low-degree whole-branch, interior-factor and exact section-degree clauses below. Coordinates c are the continuous linear equivalence from the finite basis of E, not a smaller observation space. All polynomial vanishing quantifiers range over the whole ambient frontier of the same C."))),
            DescribeRole.Theorem),
        Paragraph(Text("MC125.1–3: identify the original real polynomial ring with MvPolynomial on Fin(finrank of E) using c. The boundary ideal is exactly the vanishing ideal over the reals of c applied to frontier C: membership of r means that eval(c(y),r) is zero for every y in the entire ambient frontier. The host's equivalence between this condition and q dividing r is exactly equality of this ideal with the ideal generated by q; it includes the zero comparison polynomial. The real algebraic boundary means the common real zero set of that same ideal, equivalently the intersection of all real polynomial zero sets containing the frontier. Its complex interpretation uses the same real-coefficient ideal evaluated by the real-to-complex algebra map on complex coordinate vectors. Once the ideal is generated by q, both common zero sets are exactly the corresponding zero set of q. This is a zero-locus interpretation; it makes no claim that every real or complex zero is a Euclidean boundary point.")),
        Paragraph(Text("Define the original extended degree as the infimum, in the natural numbers with a top element, of the total degrees of all nonzero entire-boundary equations. If this family is empty the infimum is top, the stated infinity convention. If it is inhabited, the arbitrary-degree clause constructs q with minimum total degree d, so that infimum equals d and d is positive. Thus finite extended degree is equivalent to the host's existence of any nonzero entire-boundary equation, and extended degree at most three is equivalent to existence of such an equation of total degree at most three. The host's universal quantifier over each supplied equation permits exactly these existential applications; it does not assume a minimum, homogeneity, semialgebraicity, or hyperbolicity. No maximum of component degrees replaces total degree.")),
        Paragraph(Text("The geometry without a supplied quantum unit is obtained by exists_positive_functional in ConeCompactBase, which constructs a strictly positive continuous linear functional from the original salient closed cone by separation and compactness. Apply this same host to the resulting unit. When the quantum unit was already given, retain that original u throughout. ProperCone supplies closedness, convexity, nonnegative scaling and zero; Nontrivial E and the nonempty ambient interior exclude a zero cone. No smoothness, matrix model, symmetry, homogeneity of the body or initial semialgebraicity is assumed.")),
        Paragraph(Text("Construct finite coordinates from a basis of the arbitrary original finite-dimensional carrier, then retain its closed salient full cone and its arbitrary strictly positive unit. The quantum conclusion uses the existing whole normalized base, all its extreme points, the entire proper effect interval and all confirmers. Every original cone input, including mixed, unnormalized and zero mass, has an attained minimum. For every relative interior center of the original normalized section, the full relative frontier is parametrized by all unit kernel directions through the actual gauge formula, with norm and Lipschitz estimates from actual inscribed and circumscribed balls. There is no smoothness or symmetry assumption.")),
        Paragraph(Text("MC125.4 uses CircuitBalancedConfirmation.base for K, its pure definition for all extreme points P, ContinuousFrameSum.effects for the whole dual order interval from zero to the original u, and ExclusionWidthCompactness.confirmingEffects for the full confirming family. CircuitBalancedConfirmation.comparison is the infimum over all those confirming linear effects; original_quantum_consumer proves that this infimum is attained by an actual continuous confirming effect and is no larger than any other. Finite dimensionality identifies linear and continuous linear effects. The original exclusion face D at p is the subset of that same base on which comparison at p is zero. This is a definition by restriction, not an additional reconstruction or existence theorem. The type of the hyperbolic direction e remains E; the type of u remains the continuous linear dual.")),
        Paragraph(Text("In ambient dimension at least two, the specified original unit also supplies actual kernel coordinates, exact minimum-degree restriction, and polynomial homogenization of every nonzero entire section-boundary equation, including whole-boundary vanishing at the vertex. Any nonzero entire-boundary equation of any finite degree supplies native finite Boolean polynomial semialgebraicity and the actual homogeneous squarefree minimum generator. Every equation vanishing on the whole original frontier is divisible by that generator, and minimum equations are unique up to nonzero real scalar. With a boundary equation of degree at most three, orient the minimum positively on the entire original interior. Every interior direction and every original vector retain the full line polynomial degree and real splitting, including all axis inputs and repeated roots. The entire set defined by nonnegative roots is the same original closed cone, with its actual connected component and closure. The one-dimensional ray and its linear principal ideal remain explicit. The converse retains an actual whole-branch identity and concludes whole-boundary vanishing.")),
        Paragraph(Text("MC125.5 also retains every factorization of the actual arbitrary-degree minimum generator q: both factors are nonzero and homogeneous at their own total degrees, and those two degrees add to d. Hence every nonconstant divisor is homogeneous. Constant and unit factors occur at degree zero, arbitrary degree partitions are retained, and no irreducibility or squarefree hypothesis is needed for this factor inference itself. Repeated factors are covered by the general inference; the separate squarefree conclusion for the minimum excludes them there. The homogeneous-component argument applies directly to the minimum generator in this clause.")),
        Paragraph(Text("MC125.6–9 use the original unit section and its kernel: original_section_boundary proves compactness, nonempty relative interior and the exact nonzero ambient-frontier scaling identity. original_section_degree, in ambient dimension at least two, constructs actual b, J and A with x equal to u(x)b plus J(A(x)); affinePullback is the exact restriction in those coordinates. It proves nonzero restriction, equality of total degrees, minimum degree among all nonzero entire section-frontier equations, and an actual homogeneous lift of every such equation vanishing on the entire ambient frontier including zero. section_radial_geometry applies to every relative interior center, with all norm bounds, the nonsymmetric gauge difference estimate, the sphere-frontier homeomorphism and its explicit radial formula. Ambient dimension two includes the two directions of an affine line section. Ambient dimension one has a zero-dimensional compact section and is handled by the ray clause rather than a fictitious pair of section endpoints.")),
        Paragraph(Text("MC125.10–12: the compact-body factor conclusion retains every interior zero of every nonzero polynomial of degree at most three vanishing on the entire body frontier. interior_zero_factor derives nonzero derivative, actual linear factorization, a nonzero quotient of degree one less and vanishing of that quotient on the whole frontier. Its existing root obstruction retains directions with vanishing linear, quadratic or cubic coefficients; the continuous whole-frontier deletion is consumed from InteriorFactorDeletion. Minimum-degree exclusion then applies to the actual section restriction. No regularity of the convex frontier is assumed.")),
        Paragraph(Text("MC125.13–14: original_minimum_roots_and_branch supplies one orientation positive on the entire original interior, then quantifies over every interior vector e and every x in E. Its linePolynomial is the real polynomial in t evaluating q at t times c(e) minus c(x). Exact degree d and real splitting are asserted even on axis inputs, where the explicit power formula includes x equal to zero and every repeated root. The set on which all its real roots are nonnegative equals the original entire closed cone. The same interior is the whole connected component of the nonzero locus containing e, and its closure is C. The finrank-one clause constructs the original ray coordinate and linear boundary ideal without a pre-existing boundary equation. The converse is also a top-level clause, independent of any finite-equation or low-degree hypothesis on a separately supplied polynomial. In the converse, apply whole_branch_boundary_vanishing to the given homogeneous polynomial h with an actual interior direction, nonzero value there and the whole nonnegative-root branch identity, obtaining an entire-boundary equation of h's total degree; a bound of three therefore gives the original extended-degree condition. Real splitting is already part of the original hyperbolicity premise and is not needed again for this converse inference.")),
        Paragraph(Text("The statement concerns the declared finite-dimensional cone geometry and the original quantum domains. Its geometric and minimum conclusions depend on the proved semialgebraic, radial, section and whole-branch results described above.")))));
}
